package com.metaplatform.agent.evidence;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest; import org.springframework.test.context.TestPropertySource; import java.time.Instant; import static org.assertj.core.api.Assertions.assertThat;
@DataJpaTest @TestPropertySource(properties={"spring.flyway.enabled=false","spring.jpa.hibernate.ddl-auto=create-drop"}) class EvidenceRepositoryTest { @Autowired EvidenceRepository repository; @Test void crudAndCustomQuery(){ repository.save(EvidenceEntity.builder().evidenceId("e-1").type(EvidenceType.DOCUMENT).ref("doc:1").capturedAt(Instant.now()).capturedBy("agent.run-1").envelopeId("env-1").build()); assertThat(repository.findById("e-1")).isPresent(); assertThat(repository.findByEnvelopeId("env-1")).hasSize(1); } }
